                    height: 28,
                    marginLeft: 3,
                    transform: 'translateY(5px)',
                    background: C.flare,
                  }}
                />
              </div>
            ) : null}
          </WindowCard>
        </Panel>
      </div>
    </AbsoluteFill>
  );
};

