    [2.12, {x: CARD.x + PAD_X + 4, y: 648}],
    [2.16, {x: CARD.x + PAD_X + 4, y: 648}],
    [2.7, {x: 1060, y: 846}],
    [2.95, {x: 1060, y: 846}],
    [3.3, TIGHTEN],
    [4.4, TIGHTEN],
    [4.95, SEND],
  ]);
