  const dragPress = tw(t, 2.12, 2.16, 0, 1, E.linear) * (1 - tw(t, 2.7, 2.78, 0, 1, E.out));
  const cursorPress = Math.max(dragPress, press(3.36), press(5.0));
  const sendPress = press(5.0);
