      <div style={{position: 'absolute', left: 0, right: 0, top: 140, textAlign: 'center'}}>
        <Fade t={t} t0={0.0} y={14} style={{display: 'flex', justifyContent: 'center'}}>
          <Pill label="Editor" />
        </Fade>
        <div
          style={{
            marginTop: 20,
            fontFamily: sans,
            fontWeight: 500,
            fontSize: 80,
            lineHeight: 1.05,
            letterSpacing: '-0.04em',
            color: C.ink,
          }}
        >
