        style={{
          position: 'absolute',
          left: CARD.x,
          top: CARD.y,
          width: CARD.w,
          height: CARD.h,
          transform: `perspective(2000px) translateY(${(1 - kc) * 420}px) rotateX(${(1 - kc) * 32}deg)`,
