          background: C.card,
          border: `1px solid ${C.border}`,
          borderRadius: 24,
          boxShadow: '0 0 0 12px rgba(255,241,236,0.9), 0 50px 90px -40px rgba(26,22,20,0.35)',
          overflow: 'hidden',
        }}
      >
