                  mixBlendMode: 'multiply',
                  pointerEvents: 'none',
                }}
              />
            ) : null}
          </div>

          {badge > 0 ? (
            <div
              style={{
                position: 'absolute',
                right: PAD_X,
                top: 360,
                display: 'flex',
                alignItems: 'center',
                gap: 10,
