                fontFamily: sans,
                fontSize: 23,
                fontWeight: 500,
                color: C.accent,
                transform: `translateY(${(1 - badge) * 20}px) scale(${0.7 + 0.3 * badge})`,
                opacity: Math.min(1, badge * 2),
              }}
            >
              <Sparkle size={22} color={C.flare} />
              Tightened · your voice kept
            </div>
          ) : null}
        </div>

        <div
          style={{
            position: 'absolute',
            left: 0,
            right: 0,
            bottom: 0,
            height: 58,
            borderTop: `1px solid ${C.border}`,
            display: 'flex',
            alignItems: 'center',
            padding: `0 ${PAD_X - 60}px`,
            fontFamily: mono,
            fontSize: 20,
            color: C.muted,
            background: '#fcfbf9',
          }}
