                background: C.accentBg,
                border: `1px solid ${C.peach}`,
                fontFamily: sans,
                fontSize: 23,
                fontWeight: 500,
                color: C.accent,
                transform: `translateY(${(1 - badge) * 20}px) scale(${0.7 + 0.3 * badge})`,
                opacity: Math.min(1, badge * 2),
              }}
            >
