                  {m.ai ? <Sparkle size={21} color={C.accentDark} /> : null}
                  {m.label}
                </div>
                {i === 0 ? <div style={{width: 1, height: 26, background: 'rgba(255,255,255,0.18)', margin: '0 8px'}} /> : null}
              </React.Fragment>
