        {toast > 0.01 ? (
          <div
            style={{
              position: 'absolute',
              right: 20,
              top: BAR + 16,
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              padding: '14px 22px',
              borderRadius: 16,
              background: C.card,
              border: `1px solid ${C.border}`,
              boxShadow: '0 20px 40px -18px rgba(26,22,20,0.35)',
              fontFamily: sans,
              fontSize: 23,
              color: C.ink,
              transform: `translateY(${(1 - toast) * -18}px)`,
              opacity: Math.min(1, toast * 2),
