      x: mix(mix(1480, PUBLISH.x, k1), 1600, k2),
      y: mix(mix(1120, PUBLISH.y, k1), 640, k2),
      o: pr(t, 0.75, 0.15) * (1 - pr(t, 1.95, 0.25)),
    };
  })();

