        </Fade>
        <div
          style={{
            marginTop: 18,
            fontFamily: sans,
            fontWeight: 500,
            fontSize: 80,
            lineHeight: 1.05,
            letterSpacing: '-0.04em',
            color: C.ink,
            whiteSpace: 'nowrap',
          }}
        >
          <RiseWords text="Sequences that keep running." t={t} t0={0.02} stagger={0.06} />
        </div>
      </div>
      <Fade
        t={t}
        t0={0.3}
        style={{position: 'absolute', left: 1370, top: 168, width: 410, fontFamily: sans, fontSize: 25, lineHeight: 1.45, color: C.muted}}
      >
        Welcome, launch, follow-up. Publish once. Lumail handles enrolment, timing, and exits.
      </Fade>

      <div style={{position: 'absolute', left: WIN.x, top: WIN.y, width: WIN.w, height: WIN.h}}>
        <Fade t={t} t0={0.1} y={40} blur={0} style={{width: '100%', height: '100%'}}>
          <WindowCard
            title="Welcome sequence"
            style={{height: '100%'}}
            bodyStyle={{
              backgroundImage: 'radial-gradient(circle, #e2ddd6 1.6px, transparent 1.8px)',
              backgroundSize: '30px 30px',
              backgroundPosition: '15px 15px',
            }}
            right={
              live > 0.02 ? (
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    height: 44,
                    padding: '0 18px',
                    borderRadius: 999,
                    background: 'rgba(14,159,110,0.1)',
                    fontFamily: sans,
                    fontSize: 21,
                    fontWeight: 500,
                    color: C.green,
                    transform: `scale(${0.6 + 0.4 * live})`,
                    opacity: Math.min(1, live * 2),
                  }}
                >
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: 10,
                      background: C.green,
                      boxShadow: `0 0 0 ${4 + 3 * Math.sin(t * 8)}px rgba(14,159,110,0.18)`,
