                return (
                  <path
                    key={String(yes)}
                    d={`M${p0.x} ${p0.y} C${p1.x} ${p1.y} ${p2.x} ${p2.y} ${p3.x} ${p3.y}`}
                    pathLength={1}
                    strokeDasharray="1 1"
                    strokeDashoffset={1 - branchK}
                    {...connectorStyle}
                  />
                );
              })}
            </svg>

