              {opened > 0.01 ? (
                <div
                  style={{
                    position: 'absolute',
                    right: -12,
                    top: -16,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 6,
                    padding: '5px 12px 5px 8px',
                    borderRadius: 999,
                    background: C.green,
                    color: '#fff',
                    fontFamily: sans,
                    fontSize: 17,
                    fontWeight: 600,
                    transform: `scale(${opened})`,
