                >
                  <CheckIcon size={15} color="#fff" stroke={3.2} />
                  opened
                </div>
              ) : null}
            </Node>
            <Node
              x={BX}
              y={YES_Y - BH / 2}
              w={BW}
              h={BH}
              k={sp(t, 0.98, {damping: 13, stiffness: 190, mass: 0.7})}
              active={yesActive}
              icon={<MailIcon size={22} />}
              title="Yes"
              dot={C.green}
              sub={yesN > 0 ? `${fmt(yesN)} · Launch offer` : 'Launch offer'}
            />
            <Node
              x={BX}
              y={NO_Y - BH / 2}
              w={BW}
              h={BH}
              k={sp(t, 1.06, {damping: 13, stiffness: 190, mass: 0.7})}
              active={noActive}
              icon={<MailIcon size={22} />}
              title="No"
              dot={RED}
              sub={noN > 0 ? `${fmt(noN)} · Reminder` : 'Reminder'}
            />

            {sentFly > 0 && sentFly < 1 ? (
              <div
                style={{
                  position: 'absolute',
                  left: XS[1] + 38,
                  top: Y - NH / 2 - 20 - sentFly * 90,
                  color: C.flare,
                  opacity: 1 - sentFly,
                  transform: `rotate(${-12 * sentFly}deg) scale(${1 + sentFly * 0.3})`,
