  const noActive = noN > 0 ? 0.3 + 0.2 * Math.sin(t * 17 + 1) : 0;

  const waitK = tw(t, 2.4, 3.05, 0, 1, E.inOutSoft);
  const opened = sp(t, 3.3, {damping: 11, stiffness: 220, mass: 0.6});
