      </Fade>

      <div style={{position: 'absolute', left: WIN.x, top: WIN.y, width: WIN.w, height: WIN.h}}>
        <Fade t={t} t0={0.1} y={40} blur={0} style={{width: '100%', height: '100%'}}>
          <WindowCard
            title="Welcome sequence"
