        {dot ? <span style={{width: 10, height: 10, borderRadius: 10, background: dot}} /> : null}
        {title}
      </div>
      <div style={{fontSize: 19, color: C.muted, marginTop: 3, whiteSpace: 'nowrap'}}>{sub}</div>
    </div>
    {children}
  </div>
);

