            <div style={{fontSize: 21, color: C.muted}}>Subscribers stored</div>
            <div style={{fontSize: 44, fontWeight: 500, color: C.ink, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums'}}>{fmt(subs)}</div>
