              primary
              name="Creator"
              tag="For this volume"
              price="$20"
              desc="For a list that pays for itself."
              cta="Start with Creator"
              features={CREATOR}
            />
          </div>
        </Fade>
      </div>

      <ClickRipple x={TRACK.x + P0 * TRACK.w} y={TRACK.y} t={t} t0={1.5} />
      {cursor.o > 0 ? <Cursor x={cursor.x} y={cursor.y} press={press} opacity={cursor.o} /> : null}
    </AbsoluteFill>
