        ? PARTICLES.map((p, i) => {
            const a = burstAge;
            const life = pr(t, 2.12, 0.95, E.linear);
            if (life >= 1) return null;
            const x = CTA.x + p.vx * a * (1 - a * 0.45);
            const y = CTA.y + p.vy * a + 900 * a * a;
            const s = p.size * (1 - life * 0.4) * Math.min(1, a * 12);
            return (
              <div
                key={i}
                style={{
                  position: 'absolute',
                  left: x - s / 2,
                  top: y - s / 2,
                  width: s,
                  height: s,
                  transform: `rotate(${p.spin * a}deg)`,
                  opacity: 1 - life,
                  color: p.color,
                }}
              >
                {p.kind === 0 ? (
                  <Sparkle size="100%" />
