import {useLayoutEffect, useState} from 'react';
import {continueRender, delayRender} from 'remotion';

export type TextSpec = {text: string; weight: number; size: number; family: string; tracking?: number};

// Measures text widths with real DOM layout once fonts are ready, holding the render until it is done
export const useTextWidths = (specs: TextSpec[]) => {
  const [handle] = useState(() => delayRender('measure text'));
  const [widths, setWidths] = useState<number[] | null>(null);
  useLayoutEffect(() => {
    let alive = true;
    Promise.all(specs.map((s) => document.fonts.load(`${s.weight} ${s.size}px "${s.family}"`)))
      .then(() => document.fonts.ready)
      .then(() => {
        const out = specs.map((s) => {
          const el = document.createElement('span');
          el.textContent = s.text;
          Object.assign(el.style, {
            position: 'absolute',
            left: '-100000px',
            top: '0',
            visibility: 'hidden',
            whiteSpace: 'pre',
            fontFamily: `"${s.family}"`,
            fontWeight: String(s.weight),
            fontSize: `${s.size}px`,
            letterSpacing: `${s.tracking ?? 0}em`,
          });
          document.body.appendChild(el);
          const w = el.getBoundingClientRect().width;
          el.remove();
          return w;
        });
        if (alive) setWidths(out);
        continueRender(handle);
      });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return widths;
};

