  const live = sp(t, 1.42, {damping: 12, stiffness: 220, mass: 0.6});
  const enrolled = tw(t, 3.95, 6.0, 1, 1203, E.linear);
  const yesN = Math.round(tw(t, 4.2, 6.0, 0, 842, E.linear));
  const noN = Math.round(tw(t, 4.3, 6.0, 0, 361, E.linear));

