      ...STREAM.map(({s}) => {
        const c = s + segStart(STREAM_DURS, seg) + STREAM_DURS[seg] / 2;
        return Math.max(0, 1 - Math.abs(t - c) / 0.14);
      }),
    ) * 0.5;
