                <Button label="Publish" size={20} press={publishPress} style={{width: 150, height: 44, padding: 0}} />
              )
            }
          >
            <svg width={WIN.w} height={WIN.h - 64} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
              {[0, 1, 2].map((i) => (
                <line
                  key={i}
                  x1={XS[i] + NW}
                  y1={Y}
                  x2={mix(XS[i] + NW, XS[i + 1], connK(i))}
                  y2={Y}
                  {...connectorStyle}
                />
              ))}
