  const connectorStyle = {fill: 'none', stroke: '#d3cdc5', strokeWidth: 2.5, strokeLinecap: 'round' as const};

  return (
    <AbsoluteFill
      style={{
        transform: `translateY(${(1 - pushIn) * 1080}px) scale(${1 - back * 0.07})`,
