                >
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: 10,
                      background: C.green,
                      boxShadow: `0 0 0 ${4 + 3 * Math.sin(t * 8)}px rgba(14,159,110,0.18)`,
