              const loc = locate(t - s, STREAM_DURS);
              if (!loc) return null;
              const p = positionOn(loc.seg, loc.u, yes);
              if (!p) return null;
              const color = loc.seg === 7 ? (yes ? C.green : RED) : C.flare;
              return (
                <div
                  key={i}
                  style={{
                    position: 'absolute',
                    left: p.x - 7,
                    top: p.y - 7,
