  const connK = (i: number) => pr(t, 0.48 + i * 0.13, 0.25, E.inOutSoft);
  const branchK = pr(t, 0.88, 0.32, E.inOutSoft);

  const publishPress = tw(t, 1.3, 1.36, 0, 1, E.linear) * (1 - tw(t, 1.4, 1.5, 0, 1, E.out));
