                <line
                  key={i}
                  x1={XS[i] + NW}
                  y1={Y}
                  x2={mix(XS[i] + NW, XS[i + 1], connK(i))}
                  y2={Y}
                  {...connectorStyle}
                />
              ))}
              {[true, false].map((yes) => {
                const [p0, p1, p2, p3] = branchPts(yes);
                return (
                  <path
                    key={String(yes)}
                    d={`M${p0.x} ${p0.y} C${p1.x} ${p1.y} ${p2.x} ${p2.y} ${p3.x} ${p3.y}`}
                    pathLength={1}
                    strokeDasharray="1 1"
                    strokeDashoffset={1 - branchK}
                    {...connectorStyle}
                  />
