              live > 0.02 ? (
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    height: 44,
                    padding: '0 18px',
                    borderRadius: 999,
                    background: 'rgba(14,159,110,0.1)',
                    fontFamily: sans,
                    fontSize: 21,
                    fontWeight: 500,
                    color: C.green,
                    transform: `scale(${0.6 + 0.4 * live})`,
                    opacity: Math.min(1, live * 2),
                  }}
                >
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      borderRadius: 10,
                      background: C.green,
                      boxShadow: `0 0 0 ${4 + 3 * Math.sin(t * 8)}px rgba(14,159,110,0.18)`,
