              position: 'absolute',
              left: 0,
              right: 0,
              bottom: -6,
              height: 10,
              borderRadius: 10,
              background: C.flare,
              transform: `scaleX(${underline})`,
              transformOrigin: 'left center',
            }}
          />
        </span>
      </div>

      <div style={{position: 'absolute', left: 100, top: 1000, fontFamily: mono, fontSize: 24, color: 'blue'}}>
        DEBUG {JSON.stringify(widths)} idx={idx} boxW={Math.round(boxW)}
      </div>
