            position: 'relative',
            display: 'inline-block',
            width: boxW,
            height: SIZE * 1.22,
            borderRadius: 22,
            background: C.peach,
            overflow: 'hidden',
            transform: `scale(${(0.5 + 0.5 * boxIn) * (1 + landPop)})`,
            opacity: Math.min(1, boxIn * 2),
          }}
        >
          {[idx - 1, idx].map((i) => {
            if (i < 0) return null;
            const isNew = i === idx;
            const y = isNew ? (1 - k) * 100 : -k * 100;
            if (!isNew && k >= 1) return null;
            return (
              <span
                key={`${i}-${NAMES[i]}`}
                data-name="1"
                style={{
                  position: 'absolute',
                  left: BOX_PAD,
                  top: 0,
                  lineHeight: `${SIZE * 1.22}px`,
                  letterSpacing: 0,
                  transform: `translateY(${y}%)`,
                  color: i === NAMES.length - 1 && land > 0 ? C.accent : C.ink,
                  whiteSpace: 'nowrap',
                }}
              >
                “{NAMES[i]}”
              </span>
            );
          })}
        </span>
      </div>

