                      <span style={{fontWeight: 500}}>lumail - {r.tool}</span>
                      <span style={{color: C.muted}}>(MCP)</span>
                      <div style={{flex: 1}} />
                      <span style={{color: C.muted}}>⎿ </span>
                      <span style={{fontWeight: 500}}>{r.out}</span>
                    </div>
                  </Fade>
                ) : null,
              )}
              {t >= 1.85 ? (
                <Fade t={t} t0={1.85} dur={0.3} y={10} blur={3}>
                  <div style={row}>
