                  <div style={row}>
                    <span style={{width: 12, height: 12, borderRadius: 12, background: C.flare}} />
                    <span style={{fontWeight: 500}}>Done. Ready in 8 minutes.</span>
                  </div>
                </Fade>
              ) : null}
