  for (let k = 0; k < count; k++) bell(t + rnd() * dur, 1800 + rnd() * 5200, g * (0.5 + rnd() * 0.5), noise() * 0.8, 0.12 + rnd() * 0.12);
};

const square = (t, f, dur, g = 0.12, pan = 0) => {
  const i0 = idx(t);
  const lp = new Biquad();
  const c = coeffs('lp', 3200, 0.7);
  for (let n = 0; n < SR * (dur + 0.03); n++) {
