    const e = x < peak ? Math.pow(x / peak, 2) : Math.pow((1 - x) / (1 - peak), 1.6);
    const s = bp[0].run(c, noise());
    const s2 = bp[1].run(c, noise());
    const p = pan0 + (pan1 - pan0) * x;
