const bell = (t, f, g = 0.2, pan = 0, tau = 0.6) => {
  const i0 = idx(t);
  const parts = [
    [1, 1, 1],
    [2.0, 0.28, 0.6],
    [2.76, 0.16, 0.4],
    [5.4, 0.06, 0.25],
