    const a = Math.min(1, n / (SR * 0.003));
    let v = 0;
    for (const [m, amp, tm] of parts) v += Math.sin((TAU * f * m * n) / SR) * amp * Math.exp(-n / (SR * tau * tm));
    add(i0 + n, v * a * g, pan);
  }
