impact(42.0, 1.15, 1.8);
bell(42.02, 440, 0.1, 0, 1.4);
bell(42.02, 880, 0.05, 0, 1.0);
whoosh(42.6, 0.45, 0.12, 400, 2400, -0.2, 0.3);
pad(42.2, 45.0, [220, 277.18, 329.63, 440], 0.035);
pop(43.3, 520, 0.24, 0, 0.06);
click(44.12, 0.5, 0.1);
