args.command:
dev-browser --browser opus55-video <<'EOF'
const page = await browser.getPage("player");
const url = "file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/video-generation/2026-09-29-cursor-agent-claude-opus-5-5-xhigh/index.html";
await page.setViewportSize({ width: 1600, height: 1000 });
await page.goto(url);
await page.waitForFunction(() => document.querySelector('video').readyState >= 3, null, { timeout: 20000 });
const meta = await page.evaluate(() => {
  const v = document.querySelector('video');
  return {
    title: document.title,
    headings: document.querySelectorAll('h1,h2,h3,h4,h5,h6,header').length,
    visibleText: document.body.innerText.trim(),
    controls: v.controls,
    duration: v.duration, videoWidth: v.videoWidth, videoHeight: v.videoHeight,
    readyState: v.readyState, error: v.error && v.error.code,
  };
});
const playResult = await page.evaluate(() => document.querySelector('video').play().then(() => 'playing', (e) => 'rejected: ' + e.message));
let muted = false;
if (playResult !== 'playing') {
  muted = true;
  await page.evaluate(() => { const v = document.querySelector('video'); v.muted = true; return v.play(); });
}
const t0 = await page.evaluate(() => document.querySelector('video').currentTime);
await page.waitForTimeout(3000);
const mid = await page.evaluate(() => {
  const v = document.querySelector('video');
  const q = v.getVideoPlaybackQuality();
  return { currentTime: v.currentTime, paused: v.paused, totalFrames: q.totalVideoFrames, dropped: q.droppedVideoFrames,
    audioBytes: v.webkitAudioDecodedByteCount, videoBytes: v.webkitVideoDecodedByteCount };
});
await page.evaluate(() => { document.querySelector('video').currentTime = 20.5; });
await page.waitForTimeout(1200);
await saveScreenshot(await page.screenshot(), "opus55-player-1600x1000.png");
await page.evaluate(() => { document.querySelector('video').currentTime = 43.6; });
await page.waitForFunction(() => document.querySelector('video').ended, null, { timeout: 8000 });
const end = await page.evaluate(() => { const v = document.querySelector('video'); return { ended: v.ended, currentTime: v.currentTime, error: v.error && v.error.code }; });
console.log(JSON.stringify({ meta, playResult, muted, t0, mid, end }, null, 1));
EOF

