args.command:
dev-browser --browser opus55-video <<'EOF'
const page = await browser.getPage("player");
const sizes = [[1600,1000],[1000,1600],[1920,1080],[2560,1080],[800,600],[390,844]];
const out = [];
for (const [w, h] of sizes) {
  await page.setViewportSize({ width: w, height: h });
  await page.waitForTimeout(250);
  const r = await page.evaluate(() => {
    const v = document.querySelector('video');
    const b = v.getBoundingClientRect();
    return { x: b.x, y: b.y, w: b.width, h: b.height, vw: innerWidth, vh: innerHeight,
      scrollW: document.documentElement.scrollWidth, scrollH: document.documentElement.scrollHeight };
  });
  const fitsInside = r.x >= -0.5 && r.y >= -0.5 && r.x + r.w <= r.vw + 0.5 && r.y + r.h <= r.vh + 0.5;
  const ratio = r.w / r.h;
  const maximal = Math.abs(r.w - r.vw) < 1 || Math.abs(r.h - r.vh) < 1;
  const centered = Math.abs(r.x * 2 + r.w - r.vw) < 1 && Math.abs(r.y * 2 + r.h - r.vh) < 1;
  out.push({ viewport: `${w}x${h}`, rect: `${r.w.toFixed(1)}x${r.h.toFixed(1)} @ ${r.x.toFixed(1)},${r.y.toFixed(1)}`, ratio: +ratio.toFixed(4), fitsInside, maximal, centered, noScroll: r.scrollW <= r.vw && r.scrollH <= r.vh });
  if ([1000, 2560, 390].includes(w)) await saveScreenshot(await page.screenshot(), `opus55-player-${w}x${h}.png`);
}
console.log(JSON.stringify(out, null, 1));
EOF

